# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">ÇOK BASAMAKLI DOĞAL SAYILARDA TOPLAMA VE ÇIKARMA</text>\n  <rect x="20" y="48" width="320" height="190" rx="8" fill="#eff6ff" stroke="#2563eb" stroke-width="1.5"/>\n  <text x="180" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Alt Alta Eldeli Toplama İşlemi</text>\n  <text x="255" y="102" text-anchor="end" font-size="14" font-weight="bold" fill="#1e3a8a" font-family="monospace">  485.670</text>\n  <text x="255" y="124" text-anchor="end" font-size="14" font-weight="bold" fill="#1e3a8a" font-family="monospace">+ 347.850</text>\n  <line x1="110" y1="132" x2="265" y2="132" stroke="#1d4ed8" stroke-width="2"/>\n  <text x="255" y="152" text-anchor="end" font-size="14" font-weight="bold" fill="#15803d" font-family="monospace">  833.520</text>\n  <text x="180" y="180" text-anchor="middle" font-size="11" fill="#334155">• Aynı basamaklar (birler, onlar...) alt alta hizalanır.</text>\n  <text x="180" y="198" text-anchor="middle" font-size="11" fill="#334155">• Toplamı 10 veya daha büyük olan basamaktaki onluk</text>\n  <text x="180" y="216" text-anchor="middle" font-size="11" fill="#334155">bir sol basamağa «elde» olarak aktarılır.</text>\n\n  <rect x="360" y="48" width="320" height="190" rx="8" fill="#fef3c7" stroke="#d97706" stroke-width="1.5"/>\n  <text x="520" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#b45309">Onluk Bozarak Çıkarma ve Kontrol</text>\n  <text x="595" y="102" text-anchor="end" font-size="14" font-weight="bold" fill="#78350f" font-family="monospace">  920.400</text>\n  <text x="595" y="124" text-anchor="end" font-size="14" font-weight="bold" fill="#78350f" font-family="monospace">- 564.180</text>\n  <line x1="450" y1="132" x2="605" y2="132" stroke="#b45309" stroke-width="2"/>\n  <text x="595" y="152" text-anchor="end" font-size="14" font-weight="bold" fill="#b91c1c" font-family="monospace">  356.220</text>\n  <text x="520" y="180" text-anchor="middle" font-size="11" fill="#78350f">• Eksilen = Çıkan + Fark (564.180 + 356.220 = 920.400)</text>\n  <text x="520" y="198" text-anchor="middle" font-size="11" fill="#78350f">• Çıkan = Eksilen - Fark bağıntısıyla verilmeyen</text>\n  <text x="520" y="216" text-anchor="middle" font-size="11" fill="#78350f">terimler kolayca bulunur ve işlem kontrol edilir.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">ÇARPMA VE BÖLME İŞLEMİ BAĞINTILARI (KALANLI BÖLME)</text>\n  <rect x="20" y="48" width="320" height="190" rx="8" fill="#f0fdf4" stroke="#16a34a" stroke-width="1.5"/>\n  <text x="180" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Basamak Kaydırarak Çarpma</text>\n  <text x="235" y="98" text-anchor="end" font-size="13" font-weight="bold" fill="#14532d" font-family="monospace">   425</text>\n  <text x="235" y="116" text-anchor="end" font-size="13" font-weight="bold" fill="#14532d" font-family="monospace">x   36</text>\n  <line x1="130" y1="122" x2="245" y2="122" stroke="#16a34a" stroke-width="1.5"/>\n  <text x="235" y="140" text-anchor="end" font-size="13" fill="#166534" font-family="monospace">  2550 (6 x 425)</text>\n  <text x="235" y="158" text-anchor="end" font-size="13" fill="#166534" font-family="monospace">+1275  (3 onluk x 425)</text>\n  <line x1="120" y1="164" x2="245" y2="164" stroke="#16a34a" stroke-width="1.5"/>\n  <text x="235" y="182" text-anchor="end" font-size="14" font-weight="bold" fill="#15803d" font-family="monospace"> 15300</text>\n  <text x="180" y="214" text-anchor="middle" font-size="11" fill="#14532d">Onlar basamağı ile çarparken sonuç 1 basamak sola kaydırılır.</text>\n\n  <rect x="360" y="48" width="320" height="190" rx="8" fill="#faf5ff" stroke="#9333ea" stroke-width="1.5"/>\n  <text x="520" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#7e22ce">Bölme Bağıntısı ve Kalan Kuralı</text>\n  <text x="520" y="102" text-anchor="middle" font-size="13" font-weight="bold" fill="#581c87">Bölünen = (Bölen × Bölüm) + Kalan</text>\n  <text x="520" y="130" text-anchor="middle" font-size="12" font-weight="bold" fill="#6b21a8">Temel Kural: Kalan &lt; Bölen (0 ≤ Kalan &lt; Bölen)</text>\n  <text x="520" y="158" text-anchor="middle" font-size="12" fill="#4c1d95">Örnek: Bölen = 18, Bölüm = 25, En büyük Kalan = 17</text>\n  <text x="520" y="182" text-anchor="middle" font-size="12" font-weight="bold" fill="#581c87">Bölünen = (18 × 25) + 17 = 450 + 17 = 467</text>\n  <text x="520" y="214" text-anchor="middle" font-size="11" fill="#475569">Bölümde rakam indirildiğinde bölünmezse bölüme «0» konur.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">ZİHİNDEN İŞLEM VE SONUCU TAHMİN STRATEJİLERİ</text>\n  <rect x="20" y="48" width="320" height="190" rx="8" fill="#e0f2fe" stroke="#0284c7" stroke-width="1.5"/>\n  <text x="180" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#0369a1">Zihinden Çarpma ve Bölme Kısayolları</text>\n  <text x="180" y="100" text-anchor="middle" font-size="11" font-weight="bold" fill="#075985">• 10, 100, 1000 ile Çarpma/Bölme: Sıfır ekle / sil</text>\n  <text x="180" y="124" text-anchor="middle" font-size="11" fill="#0c4a6e">• 5 ile Çarpma: Sayıyı 10 ile çarpıp 2\'ye böl</text>\n  <text x="180" y="146" text-anchor="middle" font-size="11" fill="#0c4a6e">• 4 ile Çarpma: İki kez 2 katını al (×2, ×2)</text>\n  <text x="180" y="168" text-anchor="middle" font-size="11" fill="#0c4a6e">• 8 ile Çarpma: Üç kez 2 katını al (×2, ×2, ×2)</text>\n  <text x="180" y="190" text-anchor="middle" font-size="11" fill="#0c4a6e">• 5 ile Bölme: Sayıyı 2 ile çarpıp 10\'a böl</text>\n  <text x="180" y="214" text-anchor="middle" font-size="11" font-weight="bold" fill="#0369a1">Örnek: 36 × 5 ➔ (36 × 10) ÷ 2 = 360 ÷ 2 = 180</text>\n\n  <rect x="360" y="48" width="320" height="190" rx="8" fill="#fdf2f8" stroke="#db2777" stroke-width="1.5"/>\n  <text x="520" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#be185d">Yuvarlama ve Uyuşan Sayılarla Tahmin</text>\n  <text x="520" y="100" text-anchor="middle" font-size="11" font-weight="bold" fill="#831843">• Basamağa Yuvarlama:</text>\n  <text x="520" y="120" text-anchor="middle" font-size="11" fill="#9d174d">Sağdaki rakam &lt; 5 ise alt basamağa,</text>\n  <text x="520" y="138" text-anchor="middle" font-size="11" fill="#9d174d">≥ 5 ise üst basamağa yuvarlanır.</text>\n  <text x="520" y="164" text-anchor="middle" font-size="11" font-weight="bold" fill="#831843">• Bölmede Uyuşan Sayılar:</text>\n  <text x="520" y="184" text-anchor="middle" font-size="11" fill="#9d174d">Bölünen, bölenin tam katı olan en yakın sayıya</text>\n  <text x="520" y="202" text-anchor="middle" font-size="11" fill="#9d174d">tamamlanır (Örn: 358 ÷ 6 ➔ 360 ÷ 6 = 60).</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
